<?php if($thread['mode']==='question'): ?><section class="question-status panel"><span class="quick-icon"><?= icon((int)$thread['accepted_comment_id']?'check':'message') ?></span><div><span class="eyebrow">COMMUNITY / Q&amp;A</span><h3><?= t((int)$thread['accepted_comment_id']?'An answer found its way here.':'Good questions open new possibilities.') ?></h3><p><?= t('Reply below. The author can mark an approved answer as accepted.') ?></p><?php if((int)$thread['accepted_comment_id']): ?><a class="text-link" href="#comment-<?= (int)$thread['accepted_comment_id'] ?>"><?= t('Jump to accepted answer') ?><?= icon('arrow') ?></a><?php endif ?></div></section>
<?php partial('bounty_panel',['thread'=>$thread,'item'=>$item]); ?>
<?php elseif($thread['mode']==='poll'): ?><section class="poll-panel panel" data-poll-panel><div class="section-heading"><div><span class="eyebrow">COMMUNITY / ONE PERSON, ONE VOTE</span><h3><?= e($thread['poll_question']) ?></h3></div><span class="pill"><?= t($thread['closed']?'Poll closed':'Open poll') ?></span></div>
<?php if($thread['can_see_results']): ?><div class="poll-results"><?php foreach($thread['options'] as $option): ?><div class="poll-result"><div class="row between"><span><?= e($option['label']) ?><?= in_array((int)$option['id'],$thread['choices'],true)?' '.t('Your choice'):'' ?></span><strong><?= e($option['percent']) ?>%</strong></div><div class="poll-track" role="meter" aria-label="<?= e($option['label']) ?>" aria-valuemin="0" aria-valuemax="100" aria-valuenow="<?= e($option['percent']) ?>"><span style="--poll-share:<?= e($option['percent']) ?>%"></span></div><small class="hint"><?= (int)$option['votes'] ?> <?= t('votes') ?></small></div><?php endforeach ?></div><p class="hint"><?= t('Total voters') ?>: <?= (int)$thread['total'] ?><?php if((int)$thread['max_choices']>1): ?> &middot; <?= t('Percentages are based on voters, not total selections.') ?><?php endif ?></p><?php endif ?>
<?php if(!$thread['closed'] && !$thread['choice']): ?><?php if($me): ?><?= form_start('poll_vote','','poll-form') . hidden('content_id',$item['id']) ?><fieldset><legend><?= t((int)$thread['max_choices']>1?'Choose up to the allowed number of options':'Choose one option') ?><?php if((int)$thread['max_choices']>1): ?> (<?= (int)$thread['max_choices'] ?>)<?php endif ?></legend><?php foreach($thread['options'] as $option): ?><label class="poll-choice"><input type="<?= (int)$thread['max_choices']>1?'checkbox':'radio' ?>" name="<?= (int)$thread['max_choices']>1?'option_ids[]':'option_id' ?>" value="<?= (int)$option['id'] ?>" <?= (int)$thread['max_choices']===1?'required':'' ?>><span><?= e($option['label']) ?></span><?= icon('check') ?></label><?php endforeach ?></fieldset><?php button('Cast your vote','','check'); ?></form><?php else: ?><a class="btn secondary" href="<?= e(url('login')) ?>"><?= t('Sign in to vote') ?><?= icon('arrow') ?></a><?php endif ?><?php elseif($thread['choice']): ?><p class="hint"><?= icon('check') ?><?= t('Your vote was recorded.') ?></p><?php endif ?>
<?php if(!$thread['can_see_results']): ?><p class="hint"><?= t($thread['results_rule']==='closed'?'Results are private until the poll closes.':'Vote to see the results.') ?></p><?php endif ?><?php if((int)$thread['closes_at']): ?><p class="hint"><?= t('Closes at') ?> <?= dt((int)$thread['closes_at'],'Y.m.d H:i') ?></p><?php endif ?></section><?php endif ?>
